package main

import "sync"

// ❌ OLD: A common wrong assumption — that sync.Mutex hands the lock
// to the longest-waiting goroutine every time. In NORMAL mode, a
// goroutine that arrives just as the lock is released can BARGE ahead
// of goroutines that have been waiting. Under heavy contention, a
// unlucky waiter could wait far longer than the queue order suggests.
var mu sync.Mutex

func worker() {
	mu.Lock() // ❌ OLD: may be barged by newcomers under contention
	defer mu.Unlock()
	// critical section
}

// The mutex is still CORRECT (mutual exclusion holds) — the surprise
// is the fairness behavior, not the safety.

package main

import (
	"sync"
	"time"
)

// ✅ NEW: Know that sync.Mutex self-balances throughput and fairness:
// - Normal mode: barging allowed -> high throughput, some waiting
//   goroutines may be overtaken.
// - After a waiter waits ~1ms, the mutex switches to STARVATION mode:
//   unlock hands the lock directly to the longest-waiting goroutine
//   (FIFO), new arrivals queue, no barging — bounding worst-case
//   wait latency.
// - Once the starved waiter gets the lock (or its wait drops below
//   1ms), it returns to normal mode.
var mu sync.Mutex

func worker(id int) {
	mu.Lock()
	defer mu.Unlock()

	// Heavy contention with short critical sections is the scenario
	// where starvation mode kicks in. If you need strict FIFO, that's
	// a different primitive (or acceptable here — the runtime
	// self-corrects).
	time.Sleep(time.Microsecond)
}

// Key takeaway: you do NOT configure the mode — the runtime switches
// automatically based on observed wait times.
